WITH flattened_attrs AS (SELECT id, host, latency_ms, payload_json, context, context['version'] AS version, COALESCE(context['version'], 'direct') AS version_or_default, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE host NOT IN ('h4', 'h3', 'h1')) SELECT *, FIRST_VALUE(tier, TRUE) OVER (PARTITION BY host, tier ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_tier, LAG(latency_ms, 2) OVER (PARTITION BY tier, host ORDER BY latency_ms, id) AS prev_latency_ms, LAST_VALUE(tier) IGNORE NULLS OVER (ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_tier, AVG(latency_ms) OVER (PARTITION BY tier, host ORDER BY latency_ms, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS latency_ms_avg_3, FIRST_VALUE(region) IGNORE NULLS OVER (ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region FROM flattened_attrs WHERE latency_ms < 2047
